// Step 5: merge CRM profile with the triggering event, then route to a segment.
// The webhook node wraps the payload in { headers, params, query, body } — read .body explicitly.
const event = ($('1. User Activity Webhook').item.json.body ?? $('1. User Activity Webhook').item.json);
const crm = $json.error ? {} : $json; // CRM unavailable → continue with event-only payload

// Event fields win: they describe THIS user's current state. CRM only fills gaps.
const user = {
  user_id: event.user_id,
  name: event.name ?? crm.name,
  email: event.email ?? crm.email,
  country: event.country ?? crm.country,
  subscription: event.subscription ?? crm.subscription ?? 'free',
  last_active_days: Number(event.last_active_days ?? crm.last_active_days),
  core_actions_last_30_days: Number(event.core_actions_last_30_days ?? crm.core_actions_last_30_days ?? 0),
  goal: event.goal ?? crm.goal,
  preferred_channel: crm.preferred_channel ?? 'Email',
};

let segment = 'At-Risk';
if (user.subscription === 'paid') segment = 'Paid Subscriber';
else if (user.subscription === 'trial') segment = 'Free User / Trial Expired';
else if (user.core_actions_last_30_days >= 15) segment = 'Highly Engaged / Inactive';
else if (user.core_actions_last_30_days < 5) segment = 'Low Engagement';

return { json: { ...user, first_name: (user.name || 'there').split(' ')[0], segment_name: segment } };

