// Step 6b: parse model output. If the model failed (503 overload, 429, timeout, bad JSON),
// fall back to a SEGMENT-SPECIFIC template so each scenario still gets distinct copy.
const user = $('5. Segment User').item.json;
const name = user.first_name || 'there';
const n = user.core_actions_last_30_days;

let parsed = null;
let failure = null;
try {
  if ($json.error) failure = $json.error.description || $json.error.message || 'LLM request failed';
  const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) parsed = JSON.parse(text);
  else if (!failure) failure = 'Empty model response';
} catch (e) {
  failure = 'Model returned invalid JSON';
}

const TEMPLATES = {
  'Highly Engaged / Inactive': {
    subject: `Pick up where you left off, ${name}`,
    body: `Hi ${name}, you completed ${n} actions last month — that's a real habit. Two minutes today keeps your streak alive.`,
    cta: 'Resume my plan', recommendation: 'Progress continuity reminder', suggestedChannel: 'Email', confidence: 0.82,
  },
  'Paid Subscriber': {
    subject: `${name}, your progress report is ready`,
    body: `Hi ${name}, your premium insights from last month are waiting — including features you haven't opened yet.`,
    cta: 'View my insights', recommendation: 'Advanced feature insights', suggestedChannel: 'Email', confidence: 0.8,
  },
  'Free User / Trial Expired': {
    subject: `Your trial in numbers, ${name}`,
    body: `Hi ${name}, you logged ${n} actions during your trial. Keep your progress and premium features with one tap.`,
    cta: 'Keep my progress', recommendation: 'Trial recap & upgrade preview', suggestedChannel: 'Push Notification', confidence: 0.8,
  },
  'Low Engagement': {
    subject: `One small step, ${name}`,
    body: `Hi ${name}, getting started is the hardest part. Pick a ready-made template and you're done in under five minutes.`,
    cta: 'Browse templates', recommendation: 'Quick-start tips & templates', suggestedChannel: 'Push Notification', confidence: 0.78,
  },
  'At-Risk': {
    subject: `Ready to restart your routine, ${name}?`,
    body: `Hi ${name}, your plan is saved exactly where you left it. Restart with a lighter first week.`,
    cta: 'Restart my routine', recommendation: 'Routine reset reminder', suggestedChannel: 'In-App Message',
    confidence: 0.62, // ambiguous segment → below the gate → human review
  },
};

const ai_source = parsed ? 'llm' : 'fallback-template';
if (!parsed) {
  parsed = { ...(TEMPLATES[user.segment_name] ?? TEMPLATES['At-Risk']), rationale: `Fallback template for segment "${user.segment_name}" (${failure}).` };
}

return { json: { ...user, ai_data: parsed, ai_source, ai_error: failure } };

// Low-confidence output is held for a person instead of being sent.
return {
  json: {
    status: 'FLAGGED_HUMAN_REVIEW',
    user_id: $json.user_id,
    segment: $json.segment_name,
    recommendation: $json.ai_data?.recommendation,
    confidence: $json.ai_data?.confidence,
    reason: 'Confidence below the review threshold',
  },
};
